let contributions=[],officeProjects=[],officeProject=null,officeTab='overview',officeMessages=[],communityFilter='',groupFilter='',demoMode=location.pathname==='/demo',demoData=null;
function checkJoinRoles(){}function limitRoles(){}
function av(p,size=''){return `<span class="avatar ${size}">${p?.photo?`<img src="${esc(p.photo)}" alt="${esc(p.name)}">`:initials(p?.name||'Member')}</span>`}
function render(){if(route==='rate-card'){document.documentElement.dataset.theme=state.theme;document.getElementById('app').innerHTML=renderSharedRateCard();return}if(route==='project-invite'){document.documentElement.dataset.theme=state.theme;document.getElementById('app').innerHTML=renderProjectInvite();return}coreRender();if(route==='app'){if(view==='office'&&officeDesk==='inbox'&&conversationId){const pane=document.getElementById('messages');if(pane)pane.scrollTop=pane.scrollHeight}if(view==='inbox'){document.querySelector('.heading')?.insertAdjacentHTML('beforeend','<button class="btn" onclick="inviteSomeone()">Invite someone via WhatsApp / email</button>')}const side=document.querySelector('.side');if(side){const post=side.querySelector('.btn.primary');if(post){post.textContent='Tap In +';post.onclick=()=>tapMenu()}}const head=document.querySelector('.topright>.avatar');if(head&&account.profile)head.innerHTML=me().photo?`<img src="${esc(me().photo)}" alt="Your profile picture">`:initials(me().name)}if(demoMode){const app=document.getElementById('app');app.insertAdjacentHTML('afterbegin',`<div class="demo-strip"><span>Demo account · Changes stay in this tab.</span><div class="row gap8"><select aria-label="Demo role" onchange="switchDemo(this.value)"><option value="creator" ${demoData.actor==='creator'?'selected':''}>Creator</option><option value="fan" ${demoData.actor==='fan'?'selected':''}>Fan</option><option value="agent" ${demoData.actor==='agent'?'selected':''}>Agent</option></select><button onclick="resetDemo()">Reset</button><a href="/">Exit demo</a></div></div>`);document.querySelectorAll('a[href^="/signout"]').forEach(a=>{a.href='/';a.textContent='Exit demo'})}}
function baseDemo(){const creator={id:'demo-creator',name:'Lebo Mokoena',kind:'industry',roles:['Artist','Producer','Director','DJ'],city:'Johannesburg',genre:'Music video',bio:'Sound, visuals and late nights.',available:true,photo:'',followers:null,engagement:null},fanProfile={id:'demo-fan',name:'Alex M',kind:'fan',roles:[],city:'Cape Town',genre:'Other',bio:'Here for the culture.'},agent={id:'demo-agent',name:'Nandi Agency',kind:'industry',roles:['Agent'],city:'Johannesburg',genre:'Other',available:true},venue={id:'demo-venue',name:'The Listening Room',kind:'industry',roles:['Venue'],city:'Johannesburg',genre:'Live performance',available:true};const work={id:'demo-work',by:creator.id,type:'work',title:'After hours — live session',description:'A late-night performance. Every sound, frame and person belongs in the story.',date:'2026-09-12',workType:'Live performance',location:venue.id,links:[{platform:'YouTube',url:'https://www.youtube.com/watch?v=jfKfPfyJRdk'}],credits:[{id:creator.id,role:'Artist'},{id:venue.id,role:'Venue'}],likes:24,reposts:5};const project={id:'demo-project',owner:creator.id,title:'After hours / next session',scope:'A three-track live session with a performance film and social cutdowns.',budget:18000,status:'In progress',version:0,members:[{person:agent.id,status:'Accepted'}],tasks:[{id:'demo-task',title:'Confirm camera crew and shot list',assignee:creator.id,due:'2026-10-15',status:'In progress'}],documents:[{id:'demo-doc',title:'Creative direction',content:'One room. Three tracks. Warm performance energy.\n\nDeliverables: performance film, three vertical cutdowns, behind-the-scenes stills.',updated:new Date().toISOString(),by:creator.id}],assets:[{id:'demo-asset',title:'Production folder',url:'https://drive.google.com/',by:creator.id}],invoices:[],approvals:[{id:'demo-proposal',budget:20000,scope:'Add a second camera and extra edit day.',by:creator.id,status:'Pending',created:new Date().toISOString()}],created:new Date().toISOString()};return {actor:'creator',profiles:[creator,fanProfile,agent,venue],posts:[work],opps:[],requests:[],invitations:[],applications:[],priv:{follows:[venue.id],likes:[],reposts:[],saved:[],gigs:[{id:'demo-gig',title:'After hours live session',date:'2026-09-12',venue:venue.id,amount:7500,paid:true,public:true,post:work.id}],permissions:[{id:'demo-grant',person:agent.id,read:true,edit:false,book:true,inbox:true,reply:true,approve:true}],socialLinks:[],moments:[{title:'Most viral moment',text:'The live session that connected the room.',url:'https://www.youtube.com/watch?v=jfKfPfyJRdk',platform:'YouTube'},{title:'Blow up',text:'',url:'',platform:'YouTube'}]},contributions:[{id:'demo-tap',by:fanProfile.id,type:'tap',title:'This session deserves another listen',description:'Tapped in with a reaction to the performance.',date:'2026-09-13',created:new Date().toISOString(),contribution:'Appreciation',original:work.id,links:work.links,group:'work:demo-work',tags:[{person:creator.id,relation:'Acknowledged'}]}],projects:[project],chats:[{id:'demo-thread',person:agent.id,name:agent.name,last:'Let’s review the scope before we confirm.',unread:1,created:new Date().toISOString()}],messages:[{id:'demo-message',sender:agent.id,body:'Let’s review the scope before we confirm.',created:new Date().toISOString()}],teamMessages:[{sender:agent.id,body:'The new scope is ready for approval.',created:new Date().toISOString()}]}}
function persistDemo(){sessionStorage.setItem('tappedin-demo-v3',JSON.stringify(demoData))}
function demoActor(){return demoData.profiles.find(p=>p.id==='demo-'+demoData.actor)}
async function switchDemo(actor){demoData.actor=actor;persistDemo();await refreshAccount();await refreshThreads();memberAccess=actor==='agent'?[{owner:'demo-creator',name:'Lebo Mokoena',read:true,book:true,inbox:true,reply:true,approve:true}]:[];officeProject=null;conversationId=null;render()}
function resetDemo(){demoData=baseDemo();persistDemo();location.reload()}
async function api(path,method='GET',data){if(demoMode){if(!demoData){try{demoData=JSON.parse(sessionStorage.getItem('tappedin-demo-v3'))}catch{}if(!demoData)demoData=baseDemo()}const r=await demoApi(path,method,data);return structuredClone(r)}const result=await liveApi(path,method,data);if(path==='/api/bootstrap'){contributions=(await liveApi('/api/v3/contributions')).contributions;if(result.profile)officeProjects=(await liveApi('/api/v3/office')).projects}return result}
async function demoApi(path,method,data){const who=demoActor(),owner=who.id==='demo-creator';for(const p of demoData.profiles){p.socials=p.socials||[];p.links=p.links||[];p.work=p.work||0;p.bookings=p.bookings||[]}if(path==='/api/bootstrap'){contributions=demoData.contributions;officeProjects=demoOfficeList(who);const priv=owner?demoData.priv:{...demoData.priv,gigs:[],permissions:[]};return {signedIn:true,profile:who,identity:{name:who.name,email:'demo@tappedin.local'},version:0,state:{...priv,rateCard:priv.rateCard||emptyRateCard(),profiles:demoData.profiles,posts:demoData.posts,opps:demoData.opps,requests:demoData.requests,invitations:demoData.invitations,applications:demoData.applications,userMode:who.kind}}}if(path==='/api/sync'){if(owner)demoData.priv=data.private;const ix=demoData.profiles.findIndex(p=>p.id===who.id);demoData.profiles[ix]=data.profile;for(const [kind,changes]of Object.entries(data.changes)){for(const c of changes){demoData[kind]=demoData[kind].filter(x=>x.id!==c.id);if(!c.delete)demoData[kind].push(c.data)}}persistDemo();return {version:0}}if(path==='/api/threads')return method==='GET'?{threads:demoData.chats}:{id:'demo-thread'};if(path.startsWith('/api/threads/')){if(method==='POST')demoData.messages.push({id:uid(),sender:who.id,body:data.body,created:new Date().toISOString()});persistDemo();return {messages:demoData.messages}}if(path==='/api/represented')return {members:demoData.actor==='agent'?[{owner:'demo-creator',name:'Lebo Mokoena',read:true,book:true,inbox:true,reply:true,approve:true}]:[]};if(path.startsWith('/api/agent/'))return {name:'Lebo Mokoena',scopes:{read:true,edit:false,book:true},gigs:demoData.priv.gigs,requests:[]};if(path==='/api/v3/rate-cards'&&method==='POST'){return {snapshot:{id:'demo-rate-card',name:who.name,roles:who.roles,photo:who.photo||'',card:demoData.priv.rateCard||emptyRateCard(),created:new Date().toISOString(),expires:new Date(Date.now()+30*86400000).toISOString()}}}if(path==='/api/v3/contributions'){if(method==='POST'){const group=data.original?'work:'+data.original:data.type==='checkin'?'event:'+data.venue+data.date+data.event.trim().toLowerCase():'media:'+data.links[0].url;demoData.contributions.push({...data,id:uid(),by:who.id,group,created:new Date().toISOString()});persistDemo();return {contribution:demoData.contributions.at(-1)}}return {contributions:demoData.contributions}}if(path==='/api/v3/office'){if(method==='POST'){demoData.projects.push({...data.project,id:uid(),owner:who.id,scope:data.project.scope||'',budget:0,status:'Planning',version:0,members:data.project.team?(demoData.projects.find(p=>p.id===data.project.team)?.members||[]).filter(m=>m.status==='Accepted').map(m=>({...m,status:'Invited'})):[],tasks:[],documents:[],assets:[],invoices:[],approvals:[],created:new Date().toISOString()});persistDemo();return {project:demoData.projects.at(-1)}}return {projects:demoOfficeList(who)}}if(path.startsWith('/api/v3/office/')){const p=demoData.projects.find(p=>p.id===path.split('/')[4]);if(path.endsWith('/messages')){if(method==='POST')demoData.teamMessages.push({sender:who.id,body:data.body,created:new Date().toISOString()});persistDemo();return {messages:demoData.teamMessages}}if(method==='POST'){applyOfficeDemo(p,data,who.id);p.version++;persistDemo()}return {project:p}}if(path.startsWith('/api/v3/agent-projects/'))return {projects:demoData.projects};if(path.startsWith('/api/v3/agent-inbox/')){if(path.split('/').length===5)return {threads:demoData.chats,reply:true};if(method==='POST')demoData.messages.push({sender:who.id,body:'[Nandi on behalf of Lebo] '+data.body,created:new Date().toISOString()});persistDemo();return {messages:demoData.messages,reply:true}}throw new Error('This action needs a live account.')}
function demoOfficeList(who){return demoData.projects.filter(p=>p.owner===who.id||p.members.some(m=>m.person===who.id)).map(p=>p.owner===who.id||p.members.some(m=>m.person===who.id&&m.status==='Accepted')?p:{id:p.id,type:p.type||'project',title:p.title,owner:p.owner,status:'Invitation',version:p.version,members:p.members})}
function applyOfficeDemo(p,b,id){if(b.action==='task')p.tasks.push({...b,id:uid(),status:'To do'});else if(b.action==='taskstatus')p.tasks.find(t=>t.id===b.task).status=b.status;else if(b.action==='document'){const old=p.documents.find(x=>x.id===b.document);if(old)Object.assign(old,b);else p.documents.push({...b,id:uid(),by:id,updated:new Date().toISOString()})}else if(b.action==='asset')p.assets.push({...b,id:uid(),by:id});else if(b.action==='invoice'){const subtotal=b.items.reduce((n,x)=>n+x.quantity*x.rate,0);p.invoices.push({...b,id:uid(),number:'TI-'+(p.invoices.length+1),subtotal,total:subtotal*(1+b.tax/100),status:'Draft'})}else if(b.action==='invoicestatus')p.invoices.find(x=>x.id===b.invoice).status=b.status;else if(b.action==='proposal')p.approvals.push({...b,id:uid(),by:id,status:'Pending'});else if(['approve','decline'].includes(b.action)){const a=p.approvals.find(a=>a.id===b.approval);a.status=b.action==='approve'?'Approved':'Declined';if(b.action==='approve'){p.budget=a.budget;p.scope=a.scope}}else if(b.action==='invite')p.members.push({person:b.person,status:'Invited'});else if(b.action==='accept')p.members.find(m=>m.person===id).status='Accepted';else if(b.action==='remove')p.members=p.members.filter(m=>m.person!==b.person);else if(b.action==='status')p.status=b.status}
function renderAuth(){return baseAuth()+`<div style="padding:0 7vw 50px;text-align:center"><a class="btn" href="/demo">Enter demo account</a><p style="margin-top:12px">Explore as a creator, fan or agent. Your real account stays separate.</p></div>`}

function renderLanding(){const hooks=[['Feed','See what the industry is doing.','Original work, remixes, reactions and venue check-ins meet in one feed. Tap in to a moment and see everyone behind it.','feed'],['Discover','Find your next collaborator.','Find talent, crew, brands and venues by role, location and the work they do. One person can bring every side of their craft.','discover'],['Opportunities','Turn a connection into the next job.','Find briefs and collaborations with clear roles, total budgets and individual rates. Apply, invite and build the right team.','opportunities'],['Bookings','Keep the gig and its story together.','Inside Office, manage requests, record what you earned privately, and link the finished work. Give your agent only the access you choose.','bookings'],['Inbox','Keep the conversation moving.','From Office, talk directly to the people you want to work with. Let a trusted agent read or reply on your behalf when you grant permission.','inbox'],['Office','Run the work behind the work.','Bring projects, tasks, invoices, documents, media and assets into one workspace. Collaborate with your team and agree budget and scope.','office'],['Profile','Let your work speak for you.','Your roles, socials, confirmed credits, bookings and defining moments live together. Show what you have done without sending people across separate feeds.','profile']];const hookSection=`<section class="site-section platform-hooks" id="platform"><div class="eyebrow">SEVEN WAYS TO GET TAPPED IN</div><h2>Find the people.<br>Show the work.<br>Make the next thing.</h2><div class="hook-list">${hooks.map(([name,title,copy,target],i)=>`<article class="hook-row"><div class="hook-name"><span>0${i+1}</span><h3>${name}</h3></div><div><h4>${title}</h4><p>${copy}</p><a class="text-btn" href="/demo#${target}">Explore ${name.toLowerCase()} ${icon('arrow')}</a></div></article>`).join('')}</div><div class="hero-actions"><a class="btn primary" href="/signup">Create your profile</a><a class="btn" href="/demo">Try the platform</a></div></section>`;return baseLanding().replace('<a class="btn" href="/feed">Explore the feed</a>','<a class="btn" href="/feed">Explore the feed</a><a class="text-btn" href="#platform">What’s inside</a><a class="text-btn" href="/demo">Demo login</a>').replace(/<section class="site-section"><div class="eyebrow red">BUILT AROUND WHAT YOU’VE DONE<\/div>[\s\S]*?<\/section>/,hookSection)}

function tapMenu(){if(!requireAccount())return;modal('Tap in',`<div class="stack"><button class="btn primary" onclick="communityComposer('tap')">Appreciate, remix or remake</button><button class="btn" onclick="communityComposer('checkin')">Check in at a venue</button>${!fan()?'<button class="btn" onclick="startComposer(\'work\')">Post your own work & credits</button><button class="btn" onclick="startComposer(\'brief\')">Post a brief or collaboration</button>':''}</div>`,'<button class="btn" onclick="closeModal()">Close</button>')}
function communityComposer(type='tap',original=''){if(!requireAccount())return;const venues=state.profiles.filter(p=>p.category==='Venue & Space'||p.roles.includes('Venue')),todayDate=new Date().toLocaleDateString('en-CA',{timeZone:'Africa/Johannesburg'});modal(type==='tap'?'Tap in to the work':'Check in',`<label>Title</label><input id="tap-title" maxlength="120" placeholder="What are you tapping in to?"><div class="community-pickers"><div><label>Contribution</label><select id="tap-kind">${options(type==='checkin'?['Live moment','BTS','Appreciation','Other']:['Appreciation','Remake','Remix','Cover','Dance','Reaction','BTS','Other'])}</select></div><div><label>Date</label><input id="tap-date" type="date" max="${todayDate}" value="${todayDate}"></div></div>${type==='tap'?`<label>Original work (optional)</label><select id="tap-original"><option value="">Media that isn’t in the feed yet</option>${state.posts.filter(p=>p.type==='work').map(p=>`<option value="${p.id}" ${original===p.id?'selected':''}>${esc(p.title)}</option>`).join('')}</select><div class="notice">This acknowledges the work. It does not claim ownership or a production credit. Link your remake or remix alongside the original.</div>`:`<label>Venue</label><select id="tap-venue" onchange="populateEvents()"><option value="">Choose a venue</option>${venues.map(v=>`<option value="${v.id}">${esc(v.name)} / ${v.city}</option>`).join('')}</select>${!venues.length?'<p>Add a missing venue below and invite them to TAP IN.</p>':''}<label>Event / shared moment</label><select id="tap-event-select" onchange="document.getElementById('tap-event').value=this.value"><option value="">Create a new event below</option></select><input id="tap-event" maxlength="120" placeholder="Event name or occasion">`}<label>Original media / your contribution</label><div id="tap-links"><div class="link-row"><select class="tap-platform">${options(platforms)}</select><input class="tap-url" type="url" placeholder="https://…"></div></div><button class="text-btn" onclick="addTapLink()">Add another source +</button><label>Your take (optional)</label><textarea id="tap-description" maxlength="1200" placeholder="Acknowledge the work or describe your contribution"></textarea><label>${type==='checkin'?'Who is here / with you?':'Acknowledgements (optional)'}</label><div id="tap-tags"></div><button class="text-btn" onclick="addTapTag('${type}')">Tag a person +</button><div class="notice">Tags are acknowledgements, not confirmed work credits. Check-ins are public; tag people with their permission.</div><div id="form-error" class="error"></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="publishContribution('${type}')">${type==='tap'?'Tap in':'Post check-in'}</button>`)}
function populateEvents(){const venue=document.getElementById('tap-venue').value,date=document.getElementById('tap-date').value;const events=[...new Set(contributions.filter(p=>p.type==='checkin'&&p.venue===toServer({venue}).venue&&p.date===date).map(p=>p.event))];document.getElementById('tap-event-select').innerHTML='<option value="">Create a new event below</option>'+options(events)}
function addTapLink(){document.getElementById('tap-links').insertAdjacentHTML('beforeend',`<div class="link-row"><select class="tap-platform">${options(platforms)}</select><input class="tap-url" type="url" placeholder="https://…"><button aria-label="Remove media link" onclick="this.parentElement.remove()">×</button></div>`)}
function addTapTag(type){document.getElementById('tap-tags').insertAdjacentHTML('beforeend',`<div class="credit-row tap-tag"><select class="tap-person">${state.profiles.filter(p=>p.id!=='me').map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select><select class="tap-relation">${options(type==='checkin'?['With me','Here too','Acknowledged']:['Acknowledged'])}</select><button aria-label="Remove tagged person" onclick="this.parentElement.remove()">×</button></div>`)}
async function publishContribution(type){const links=[...document.querySelectorAll('#tap-links .link-row')].map(r=>({platform:r.querySelector('select').value,url:r.querySelector('.tap-url').value.trim()})).filter(l=>l.url);if(type==='tap'&&!links.length&&!contributionPresentation.image)return error('Link the media you are acknowledging or creating.');if(links.some(l=>!safeUrl(l.url)))return error('Use HTTPS media links.');const tags=[...document.querySelectorAll('.tap-tag')].map(r=>({person:r.querySelector('.tap-person').value,relation:r.querySelector('.tap-relation').value}));const payload={type,title:document.getElementById('tap-title').value.trim(),date:document.getElementById('tap-date').value,contribution:document.getElementById('tap-kind').value,description:document.getElementById('tap-description').value,links,tags,original:document.getElementById('tap-original')?.value||'',venue:document.getElementById('tap-venue')?.value||'',event:document.getElementById('tap-event')?.value.trim()||''};if(!payload.title)return error('Add a title.');try{await api('/api/v3/contributions','POST',toServer(payload));contributions=(await api('/api/v3/contributions')).contributions;closeModal();view='feed';route='app';render();toast('You’re tapped in.');if(type==='checkin'&&checkinVenueContact)shareContact(checkinVenueContact.id,checkinVenueContact.name)}catch(e){error(e.message)}}
function postCard(p){let html=basePostCard(p);const related=contributions.filter(c=>c.original===p.id);if(p.type==='work'){html=html.replace('</article>',`<div class="community-group"><button class="text-btn" onclick="communityComposer('tap','${p.id}')">Tap in to this work</button>${related.length?`<button class="text-btn" onclick="openContributionFeed('${related[0].group}')">${related.length} fan contribution${related.length===1?'':'s'} / Shared feed</button>`:''}</div></article>`)}return html}
function contributionPerson(id){return person(idMap({id},account.profile?.id||'__none__','me').id)}
function contributionCard(p){const by=contributionPerson(p.by)||{name:'Member'},groupPosts=contributions.filter(c=>c.group===p.group);return `<article class="community-post"><div class="row gap8">${av(by)}<button class="who" onclick="openProfile('${by.id||'me'}')">${esc(by.name)}</button><span class="meta">${esc(p.contribution)} / ${fmt(p.date)}</span></div><h3><button class="post-title" onclick="openProfileContribution('${p.id}')">${esc(p.title)}</button></h3><p>${esc(p.description)}</p>${sourceLinks(p.links)}${p.type==='checkin'?`<div class="community-group"><b>${esc(contributionPerson(p.venue)?.name||p.venueName||'Venue')} / ${esc(p.event)}</b></div>`:''}${p.original?`<button class="text-btn" onclick="openWork('${p.original}')">Original work & production credits</button>`:''}<div class="check-tags">${p.tags.map(t=>{const person=contributionPerson(t.person);return person?`<button class="text-btn" onclick="openProfile('${person.id}')">${esc(person.name)} / ${esc(t.relation)}</button>`:''}).join('')}</div><div class="row gap8"><button class="text-btn" onclick="react('likes','${p.id}')">${icon('heart')}${state.likes.includes(p.id)?'Liked':'Like'}</button><button class="text-btn" onclick="react('reposts','${p.id}')">${icon('repost')}${state.reposts.includes(p.id)?'Reposted':'Repost'}</button><button class="text-btn" onclick="react('saved','${p.id}')">${icon('save')}Save</button></div><div class="community-group"><button class="btn" onclick="openContributionFeed('${p.group}')">${groupPosts.length} contribution${groupPosts.length===1?'':'s'} / Open this shared feed</button></div></article>`}
function renderFeed(){const headings=`<div class="heading"><div class="eyebrow">${groupFilter?'ONE MOMENT. EVERY CONTRIBUTION.':'CONNECTED THROUGH THE WORK'}</div><h1>${groupFilter?'The shared feed.':'The feed.'}</h1>${groupFilter?'<button class="text-btn" onclick="groupFilter=\'\';render()">Back to all work</button>':''}</div>`;const controls=`<div class="community-actions">${account.profile?'<button onclick="communityComposer(\'tap\')">Tap in +</button><button onclick="communityComposer(\'checkin\')">Check in +</button>'+(!fan()?'<button onclick="startComposer(\'work\')">Show your work +</button>':''):'<a class="btn primary" href="/signup">Join TAPPED IN</a>'}</div><div class="tabs">${[['all','For you'],['following','Following'],['reposts','Your reposts'],['saved','Saved']].map(([v,l])=>`<button class="tab ${feedTab===v?'active':''}" onclick="feedTab='${v}';render()">${l}</button>`).join('')}</div><div class="dropdown-filter"><label>Feed layer<select onchange="communityFilter=this.value;groupFilter='';render()">${options(['Everything','Original work','Fan contributions','Check-ins'],communityFilter||'Everything')}</select></label>${filterDropdown('feed-work','Work type',workTypes,feedWork,'feedWork=this.value;render()')}${filterDropdown('feed-platform','Platform',platforms,feedPlatform,'feedPlatform=this.value;render()')}<label>Order<select onchange="feedOrder=this.value;render()">${options(['Newest first','Oldest first'],feedOrder==='old'?'Oldest first':'Newest first')}</select></label></div>`;let posts=contributions.filter(p=>(communityFilter!=='Check-ins'||p.type==='checkin')&&(communityFilter!=='Fan contributions'||p.type==='tap')&&communityFilter!=='Original work'&&(!groupFilter||p.group===groupFilter));let originals=state.posts.filter(p=>groupFilter?contributions.some(c=>c.group===groupFilter&&c.original===p.id):['','Everything','Original work'].includes(communityFilter));const filter=p=>(feedTab!=='following'||state.follows.includes(idMap({id:p.by},account.profile?.id||'__none__','me').id))&&(feedTab!=='reposts'||state.reposts.includes(p.id))&&(feedTab!=='saved'||state.saved.includes(p.id))&&(!feedPlatform||p.links?.some(l=>l.platform===feedPlatform))&&(!feedWork||(p.workType||state.posts.find(w=>w.id===p.original)?.workType||state.opps.find(o=>o.id===p.opp)?.workType)===feedWork);posts=posts.filter(filter);originals=originals.filter(filter);if(!groupFilter)posts=posts.filter((p,i,all)=>all.findIndex(x=>x.group===p.group)===i&&!originals.some(w=>w.id===p.original));const combined=[...originals.map(p=>({...p,_original:true})),...posts].sort((a,b)=>(feedOrder==='Oldest first'||feedOrder==='old')?(a.date||'').localeCompare(b.date||''):(b.created||b.date||'').localeCompare(a.created||a.date||''));return headings+controls+(combined.map(p=>p._original?postCard(p):contributionCard(p)).join('')||'<div class="empty"><h3>Be part of the story.</h3><p>Tap in to existing media, check in at a venue, or show the work you made.</p></div>')}
function openContributionFeed(group){groupFilter=group;communityFilter='Everything';closeModal();nav('feed')}
function baseContributionCTA(id){return `<button class="btn" onclick="communityComposer('tap','${id}')">Tap in to this work</button>`}
const originalOpenWork=openWork;
// This wrapper is assigned after the original function definitions have loaded.
openWork=function(id){originalOpenWork(id);const foot=document.querySelector('#modal .dialog-footer')||document.querySelector('#modal .dialog-foot');if(foot)foot.insertAdjacentHTML('afterbegin',baseContributionCTA(id))};
function baseProfileWithPhoto(){return baseProfile()}
function renderProfile(){const html=baseProfileWithPhoto(),p=person(activeProfile),own=activeProfile==='me',activity=contributions.filter(c=>c.by===toServer({id:p?.id}).id);return html+(own&&!fan()&&profileTab==='history'?renderRateCardSection():'')+(profileTab==='awards'?renderAwards(p,own):'')+(profileTab!=='awards'&&activity.length?`<div class="section-label">TAP INS & CHECK INS</div>${activity.map(contributionCard).join('')}`:'')}

async function uploadPhoto(input){const file=input.files[0];if(!file)return;if(file.size>3000000)return toast('Use a picture under 3 MB.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))return toast('Use JPG, PNG or WebP.');try{let url;if(demoMode){url=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}else{const response=await fetch('/api/v3/photo',{method:'POST',headers:{'content-type':file.type},body:file});const r=await response.json();if(!response.ok)throw new Error(r.error);url=r.url}me().photo=url;await save();render();toast('Profile picture saved.')}catch(e){toast(e.message)}}
async function removePhoto(){me().photo='';await save();render()}
function renderSettings(){let html=baseSettings();html=html.replace('Booking agent access','Agent permissions').replace('Members you represent','Members you represent');if(memberAccess.length)html+=`<section class="settings-block"><h3>Shared inboxes & approvals</h3>${memberAccess.map(m=>`<div class="office-row"><b>${esc(m.name)}</b><div class="row wrap gap8"><button class="btn" onclick="openAgentInbox('${m.owner}')">Shared inbox</button><button class="btn" onclick="loadAgentProjects('${m.owner}')">Budget & scope approvals</button></div></div>`).join('')}</section>`;return html}
function grantAccess(){const agents=state.profiles.filter(p=>p.id!=='me'&&p.roles.includes('Agent'));modal('Agent permissions',agents.length?`<label>Agent</label><select id="access-person">${agents.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select>${[['read','View private fees'],['edit','Edit gig records'],['book','Manage booking requests'],['inbox','Read inbox'],['reply','Reply on my behalf'],['approve','Final approval on budget and scope']].map(([k,l])=>`<label class="radio-row"><input type="checkbox" id="access-${k}">${l}</label>`).join('')}<p>Replies identify your agent. Managing bookings alone does not allow acceptance: final approval must also be granted. Office approval gives access to the selected member’s project workspace.</p><div id="form-error" class="error"></div>`:'<p>Your agent needs a registered Agent profile first.</p>',agents.length?'<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveAccess()">Save permissions</button>':'<button class="btn" onclick="closeModal()">Close</button>')}
async function saveAccess(){const person=document.getElementById('access-person').value,g={id:uid(),person};for(const k of ['read','edit','book','inbox','reply','approve'])g[k]=document.getElementById('access-'+k).checked;g.read=g.read||g.edit;g.inbox=g.inbox||g.reply;if(!Object.keys(g).some(k=>typeof g[k]==='boolean'&&g[k]))return error('Choose at least one permission.');state.permissions=state.permissions.filter(p=>p.person!==person);state.permissions.push(g);await save();closeModal();render();toast('Agent permissions saved.')}
let sharedInboxOwner='',sharedInboxThread='';
async function openAgentInbox(owner){try{sharedInboxOwner=owner;const r=await api('/api/v3/agent-inbox/'+owner);modal('Shared inbox',`<p>Only the permissions this member granted apply. Your replies show who sent them.</p>${r.threads.map(t=>`<div class="office-row"><b>${esc(t.name)}</b><button class="btn" onclick="openSharedConversation('${t.id}')">Open</button></div>`).join('')||'<p>No conversations yet.</p>'}`,'<button class="btn" onclick="closeModal()">Done</button>')}catch(e){toast(e.message)}}
async function openSharedConversation(tid){try{sharedInboxThread=tid;const r=await api('/api/v3/agent-inbox/'+sharedInboxOwner+'/'+tid);modal('Conversation / acting as agent',`<div class="office-chat">${r.messages.map(m=>`<div class="office-row"><div><b>${esc(contributionPerson(m.sender)?.name||'Member')}</b><p>${esc(m.body)}</p></div></div>`).join('')}</div>${r.reply?'<label>Reply on behalf of this member</label><textarea id="agent-message" maxlength="3800"></textarea>':'<p>Read-only access.</p>'}<div id="form-error" class="error"></div>`,`<button class="btn" onclick="openAgentInbox('${sharedInboxOwner}')">Back</button>${r.reply?'<button class="btn primary" onclick="sendAgentMessage()">Reply as agent</button>':''}`)}catch(e){toast(e.message)}}
async function sendAgentMessage(){try{await api('/api/v3/agent-inbox/'+sharedInboxOwner+'/'+sharedInboxThread,'POST',{body:document.getElementById('agent-message').value});await openSharedConversation(sharedInboxThread)}catch(e){error(e.message)}}
async function loadAgentProjects(owner){try{const r=await api('/api/v3/agent-projects/'+owner);officeProjects=r.projects;officeProject=null;officeDesk='projects';nav('office')}catch(e){toast(e.message)}}
function officeMemberOptions(selected=''){const p=officeProject,ids=[p.owner,...p.members.filter(m=>m.status==='Accepted').map(m=>m.person)];return ids.map(id=>`<option value="${id}" ${id===selected?'selected':''}>${esc(contributionPerson(id)?.name||'Member')}</option>`).join('')}
function projectOffice(){if(!account.profile)return '<p>Sign in to open your office.</p>';if(!officeProject)return `<div class="heading"><div class="eyebrow">THE WORK BEHIND THE WORK</div><h1>Your office.</h1><p>Projects, invoices, documents, assets and the team conversation. Together.</p></div><div class="office-toolbar"><button class="btn primary" onclick="newProject()">Create project +</button><button class="text-btn" onclick="refreshOffice()">Refresh office</button></div>${officeProjects.map(p=>`<article class="office-row"><div><h3>${esc(p.title)}</h3><p>${esc(p.status)} / ${esc(contributionPerson(p.owner)?.name||'Project owner')}</p>${p.status!=='Invitation'?`<p>${money(p.budget)} approved budget / ${p.tasks?.filter(t=>t.status==='Done').length||0} of ${p.tasks?.length||0} tasks done</p>`:''}</div><button class="btn" onclick="${p.status==='Invitation'?`acceptProject('${p.id}')`:`openProject('${p.id}')`}">${p.status==='Invitation'?'Accept invitation':'Open project'}</button></article>`).join('')||'<div class="empty"><h3>Make room for the next project.</h3><p>Create a workspace, invite your team and bring the work together.</p></div>'}`;const p=officeProject,owner=p.owner===account.profile.id,canApprove=owner||memberAccess.some(m=>m.owner===p.owner&&m.approve);return `<div class="office-main"><button class="text-btn" onclick="officeProject=null;render()">${p.type==='team'?'All teams':'All projects'}</button><div class="office-toolbar" style="margin-top:22px"><div><div class="eyebrow">${esc(p.status)}</div><h2>${esc(p.title)}</h2></div><button class="text-btn" onclick="openProject('${p.id}')">Refresh</button></div><div class="office-tabs">${['overview','tasks','documents','assets','invoices','team','chat','approvals'].map(t=>`<button class="${officeTab===t?'active':''}" onclick="setOfficeTab('${t}')">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div>${officeTab==='overview'?`<div class="office-metrics"><div><small>APPROVED BUDGET</small><strong>${money(p.budget)}</strong></div><div><small>TASKS COMPLETE</small><strong>${p.tasks.filter(t=>t.status==='Done').length} / ${p.tasks.length}</strong></div><div><small>INVOICED</small><strong>${money(p.invoices.filter(i=>i.status!=='Cancelled').reduce((n,i)=>n+i.total,0))}</strong></div></div>${p.linked?`<button class="text-btn" onclick="${p.linkedKind==='opps'?`openOpportunity('${p.linked}')`:`openWork('${p.linked}')`}">Open linked work / brief</button>`:''}<h3>Approved scope</h3><p class="office-document">${esc(p.scope||'Submit a budget and scope proposal to agree the work.')}</p><div class="row gap8 wrap" style="margin-top:24px"><button class="btn" onclick="officeForm('proposal')">Propose budget & scope</button>${owner?`<label>Project status<select onchange="officeAction({action:'status',status:this.value})">${options(['Planning','In progress','Delivered','Archived'],p.status)}</select></label>`:''}</div>`:officeTab==='tasks'?`<button class="btn primary" onclick="officeForm('task')">Add task +</button>${p.tasks.map(t=>`<div class="office-row"><div><b>${esc(t.title)}</b><p>${esc(contributionPerson(t.assignee)?.name||'Member')}${t.due?' / Due '+fmt(t.due):''}</p></div><select aria-label="Task status" onchange="officeAction({action:'taskstatus',task:'${t.id}',status:this.value})">${options(['To do','In progress','Done'],t.status)}</select></div>`).join('')||'<p style="margin-top:20px">No tasks yet.</p>'}`:officeTab==='documents'?`<button class="btn primary" onclick="officeForm('document')">Create document +</button>${p.documents.map(x=>`<div class="office-row"><div><b>${esc(x.title)}</b><p>${esc(contributionPerson(x.by)?.name||'Member')}</p></div><div class="row gap8"><button class="btn" onclick="viewDocument('${x.id}')">Read</button><button class="text-btn" onclick="officeForm('document','${x.id}')">Edit</button></div></div>`).join('')||'<p style="margin-top:20px">Store your briefs, treatments, shot lists, notes and agreements here.</p>'}`:officeTab==='assets'?`<button class="btn primary" onclick="officeForm('asset')">Link asset +</button><button class="btn" onclick="officeUploadForm()">Upload media +</button><p style="margin-top:20px">Google Drive folders, Dropbox links, references and deliverables. Access stays controlled by the source provider.</p>${p.assets.map(x=>`<div class="office-row"><b>${esc(x.title)}</b>${x.file?`<div class="row gap8"><button class="btn" onclick="previewOfficeFile('${x.id}')">View media</button><a class="text-btn" href="${esc(x.url)}${x.url.startsWith('data:')?'':'?download=1'}" target="_blank" rel="noopener noreferrer">Download</a></div>`:`<a class="btn" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">Open asset</a>`}</div>`).join('')}`:officeTab==='invoices'?`${owner?'<button class="btn primary" onclick="officeForm(\'invoice\')">Create invoice +</button>':''}<p style="margin-top:20px">Generate a document, issue it yourself, and track payment. Status does not collect or transfer money.</p>${p.invoices.map(i=>`<div class="office-row"><div><b>${esc(i.number)} / ${esc(i.client)}</b><p>${money(i.total)} / Due ${fmt(i.due)}</p><button class="text-btn" onclick="viewInvoice('${i.id}')">View / print / save PDF</button></div>${owner?`<select aria-label="Invoice status" onchange="officeAction({action:'invoicestatus',invoice:'${i.id}',status:this.value})">${options(['Draft','Issued','Paid','Cancelled'],i.status)}</select>`:`<span>${i.status}</span>`}</div>`).join('')}`:officeTab==='team'?`${owner?'<button class="btn primary" onclick="officeForm(\'invite\')">Invite teammate +</button><button class="btn" onclick="inviteOutsideProject()">Invite via WhatsApp / email</button>':''}<div class="office-row"><b>${esc(contributionPerson(p.owner)?.name||'Owner')}</b><span>Owner / final approval</span></div>${p.members.map(m=>`<div class="office-row"><b>${esc(contributionPerson(m.person)?.name||'Member')}</b><div class="row gap8"><span>${m.status}</span>${owner?`<button class="text-btn" onclick="officeAction({action:'remove',person:'${m.person}'})">Remove</button>`:''}</div></div>`).join('')}<p>Invited members accept from their office. Accepted members share tasks, documents, assets and team chat. Final budget and scope approval stays with the owner or an authorised agent.</p>`:officeTab==='chat'?`<div class="office-toolbar"><h3>Team messages</h3><button class="text-btn" onclick="refreshOfficeMessages()">Refresh messages</button></div><div class="office-chat" id="team-chat">${officeMessages.map(m=>`<div class="office-row"><div><b>${esc(contributionPerson(m.sender)?.name||'Member')}</b><p>${esc(m.body)}</p><small>${new Date(m.created).toLocaleString('en-ZA',{timeZone:'Africa/Johannesburg'})}</small></div></div>`).join('')||'<p>Keep the team conversation with the project.</p>'}</div><form onsubmit="event.preventDefault();sendOfficeMessage()"><label>Message your team</label><textarea id="office-message" maxlength="4000" required></textarea><button class="btn primary" type="submit">Send to team</button></form>`:`<button class="btn primary" onclick="officeForm('proposal')">Submit budget & scope</button>${p.approvals.map(a=>`<div class="office-row"><div><h3>${money(a.budget)} / ${esc(a.status)}</h3><p class="office-document">${esc(a.scope)}</p><p>Proposed by ${esc(contributionPerson(a.by)?.name||'Member')}${a.approvedBy?' / Reviewed by '+esc(contributionPerson(a.approvedBy)?.name||'Agent'):''}</p></div>${a.status==='Pending'&&canApprove?`<div class="row wrap gap8"><button class="btn primary" onclick="officeAction({action:'approve',approval:'${a.id}'})">Final approval</button><button class="btn" onclick="officeAction({action:'decline',approval:'${a.id}'})">Decline</button></div>`:''}</div>`).join('')||'<p style="margin-top:20px">No proposals yet.</p>'}`}</div>`}
async function refreshOffice(){try{officeProjects=(await api('/api/v3/office')).projects;render()}catch(e){toast(e.message)}}
function newProject(team=false){creatingTeam=team;if(!requireAccount(true))return;modal(team?'Create a team':'Create a project',`<label>${team?'Team name':'Project name'}</label><input id="project-title" maxlength="120">${!team?`<label>Bring a team (optional)</label><select id="project-team"><option value="">Build a new project team</option>${officeProjects.filter(p=>p.type==='team'&&p.owner===account.profile.id).map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('')}</select>`:''}<label>Linked work / brief (optional)</label><select id="project-linked"><option value="">Standalone project</option>${[...state.posts.filter(p=>p.type==='work'),...state.opps].map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('')}</select><label>Initial scope / notes</label><textarea id="project-scope" maxlength="3000"></textarea><div id="form-error" class="error"></div>`,'<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="createProject()">Create workspace</button>')}
async function createProject(){try{const r=await api('/api/v3/office','POST',{project:{type:creatingTeam?'team':'project',team:document.getElementById('project-team')?.value||'',title:document.getElementById('project-title').value,scope:document.getElementById('project-scope').value,linked:document.getElementById('project-linked').value}});officeProject=r.project;officeDesk=creatingTeam?'teams':'projects';officeTab=creatingTeam?'team':'overview';await refreshOffice();closeModal();nav('office')}catch(e){error(e.message)}}
async function openProject(id){try{officeProject=(await api('/api/v3/office/'+id)).project;officeDesk=officeProject.type==='team'?'teams':'projects';if(officeTab==='chat')await fetchOfficeMessages();nav('office')}catch(e){toast(e.message)}}
async function acceptProject(id){try{await api('/api/v3/office/'+id,'POST',{action:'accept'});await refreshOffice();await openProject(id)}catch(e){toast(e.message)}}
async function setOfficeTab(t){officeTab=t;if(t==='chat')await fetchOfficeMessages();render()}
async function officeAction(data){showSaveStatus('Saving project…');try{const r=await api('/api/v3/office/'+officeProject.id,'POST',{...data,version:officeProject.version});officeProject=r.project;const ix=officeProjects.findIndex(p=>p.id===officeProject.id);if(ix>=0)officeProjects[ix]=officeProject;closeModal();render();showSaveStatus('Saved');setTimeout(()=>showSaveStatus(''),1500);toast(data.action==='status'?'Project status saved: '+officeProject.status+'.':'Project changes saved.');return true}catch(e){showSaveStatus('Not saved');if(data.action==='status')render();error(e.message);toast(e.message);return false}}
function officeForm(action,id=''){const p=officeProject,old=id?p.documents.find(d=>d.id===id):null;let content='';if(action==='task')content=`<label>Task</label><input id="of-title" maxlength="200"><label>Assignee</label><select id="of-assignee">${officeMemberOptions()}</select><label>Due date (optional)</label><input id="of-due" type="date">`;if(action==='document')content=`<label>Document title</label><input id="of-title" maxlength="120" value="${esc(old?.title||'')}"><label>Document</label><textarea id="of-content" maxlength="20000" style="min-height:240px">${esc(old?.content||'')}</textarea>`;if(action==='asset')content='<label>Asset name</label><input id="of-title" maxlength="120"><label>Google Drive / asset URL</label><input id="of-url" type="url" placeholder="https://drive.google.com/…">';if(action==='invite')content=`<label>Teammate</label><select id="of-person">${state.profiles.filter(m=>m.id!=='me'&&!p.members.some(x=>x.person===toServer({person:m.id}).person)).map(m=>`<option value="${toServer({person:m.id}).person}">${esc(m.name)}</option>`).join('')}</select><p>They’ll receive an invitation in their office.</p>`;if(action==='proposal')content=`<label>Total budget (ZAR)</label><input id="of-budget" type="number" min="0" value="${p.budget}"><label>Scope / deliverables</label><textarea id="of-scope" maxlength="3000">${esc(p.scope)}</textarea><p>Budget and scope only change after final approval by the owner or an agent with approval permission.</p>`;if(action==='invoice')content=`<label>Client / billing details</label><textarea id="of-client" maxlength="150" placeholder="Client name and billing details"></textarea><label>Payment due</label><input id="of-due" type="date"><label>Items / quantity / rate (ZAR)</label><div id="invoice-lines">${invoiceLine()}</div><button class="text-btn" onclick="document.getElementById('invoice-lines').insertAdjacentHTML('beforeend',invoiceLine())">Add line item +</button><label>Tax (%)</label><select id="of-tax"><option value="0">No tax / 0%</option><option value="15">VAT / 15%</option></select><p>Only apply VAT if you are registered. The invoice is stored in this project.</p>`;modal({task:'Add task',document:'Project document',asset:'Link work asset',invite:'Invite teammate',proposal:'Budget & scope proposal',invoice:'Create invoice'}[action],content+'<div id="form-error" class="error"></div>',`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveOfficeForm('${action}','${id}')">${action==='proposal'?'Submit for approval':'Save'}</button>`)}
function invoiceLine(){return '<div class="invoice-line"><input class="invoice-description" placeholder="Service / deliverable" maxlength="200"><input class="invoice-quantity" type="number" min="1" value="1" aria-label="Quantity"><input class="invoice-rate" type="number" min="0" placeholder="Rate" aria-label="Rate"><button onclick="this.parentElement.remove()" aria-label="Remove invoice line">×</button></div>'}
async function saveOfficeForm(action,id){const value=k=>document.getElementById('of-'+k)?.value||'',b={action};if(action==='task')Object.assign(b,{title:value('title'),due:value('due'),assignee:value('assignee')});if(action==='document')Object.assign(b,{title:value('title'),content:value('content'),document:id});if(action==='asset')Object.assign(b,{title:value('title'),url:value('url')});if(action==='invite')b.person=value('person');if(action==='proposal')Object.assign(b,{budget:Number(value('budget')),scope:value('scope')});if(action==='invoice')Object.assign(b,{client:value('client'),due:value('due'),tax:Number(value('tax')),items:[...document.querySelectorAll('.invoice-line')].map(r=>({description:r.querySelector('.invoice-description').value,quantity:Number(r.querySelector('.invoice-quantity').value),rate:Number(r.querySelector('.invoice-rate').value)}))});await officeAction(b)}
function viewDocument(id){const d=officeProject.documents.find(d=>d.id===id);modal(esc(d.title),`<div class="office-document">${esc(d.content)}</div>`,`<button class="btn" onclick="downloadDocument('${id}')">Download .txt</button><button class="btn" onclick="closeModal()">Done</button>`)}
function downloadDocument(id){const d=officeProject.documents.find(d=>d.id===id),u=URL.createObjectURL(new Blob([d.title+'\n\n'+d.content],{type:'text/plain'})),a=document.createElement('a');a.href=u;a.download=d.title.replace(/[^a-z0-9_-]/gi,'_')+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function viewInvoice(id){const i=officeProject.invoices.find(i=>i.id===id);modal('Invoice',`<div id="invoice-print"><div class="brand">TAPPED <span>IN</span></div><h2 style="margin:25px 0">INVOICE / ${esc(i.number)}</h2><p>From: ${esc(contributionPerson(officeProject.owner)?.name||'Creator')}</p><p style="white-space:pre-wrap;margin:15px 0">Bill to: ${esc(i.client)}</p><p>Project: ${esc(officeProject.title)}<br>Due: ${fmt(i.due)} / ${esc(i.status)}</p>${i.items.map(x=>`<div class="office-row"><span>${esc(x.description)} / ${x.quantity} × ${money(x.rate)}</span><b>${money(x.quantity*x.rate)}</b></div>`).join('')}<p>Subtotal: ${money(i.subtotal)}<br>Tax: ${i.tax}%</p><h2 style="margin:20px 0">TOTAL ${money(i.total)}</h2></div>`,'<button class="btn" onclick="closeModal()">Done</button><button class="btn primary" onclick="window.print()">Print / save PDF</button>')}
async function fetchOfficeMessages(){officeMessages=(await api('/api/v3/office/'+officeProject.id+'/messages')).messages}
async function refreshOfficeMessages(){try{await fetchOfficeMessages();render()}catch(e){toast(e.message)}}
async function sendOfficeMessage(){const el=document.getElementById('office-message'),body=el.value.trim();if(!body)return;try{await api('/api/v3/office/'+officeProject.id+'/messages','POST',{body});await fetchOfficeMessages();render()}catch(e){toast(e.message)}}
setInterval(()=>{if(account.profile&&view==='office'&&officeProject&&officeTab==='chat')refreshOfficeMessages()},12000);

function safeUrl(s){try{const u=new URL(s);return u.protocol==='https:'&&!u.username&&!u.password}catch{return false}}

let officeDesk=['inbox','bookings','teams','projects'].includes(location.hash.split('/')[1])?location.hash.split('/')[1]:['inbox','bookings'].includes(location.hash.slice(1))?location.hash.slice(1):'projects',creatingTeam=false,profilePhotoDraft;
function setOfficeDesk(desk){officeDesk=desk;officeProject=null;nav('office')}
function renderOffice(){const tabs=`<div class="office-tabs office-desk-tabs">${[['inbox','Inbox'],...(!fan()?[['bookings','Bookings']]:[]),['teams','Teams'],['projects','Projects']].map(([v,l])=>`<button class="${officeDesk===v?'active':''}" onclick="setOfficeDesk('${v}')">${l}${v==='inbox'&&threads.some(t=>t.unread)?' / '+threads.reduce((n,t)=>n+(t.unread||0),0):''}</button>`).join('')}</div>`;if(officeProject)return tabs+projectOffice();if(officeDesk==='inbox')return tabs+(memberAccess.some(m=>m.inbox)?`<div class="office-toolbar"><span>Shared inboxes</span>${memberAccess.filter(m=>m.inbox).map(m=>`<button class="text-btn" onclick="openAgentInbox('${m.owner}')">${esc(m.name)} / agent access</button>`).join('')}</div>`:'')+renderInbox();if(officeDesk==='bookings')return tabs+renderBookings();const team=officeDesk==='teams',items=officeProjects.filter(p=>team?p.type==='team':p.type!=='team');return `<div class="heading"><div class="eyebrow">EVERYTHING BEHIND THE WORK</div><h1>Your office.</h1><p>Your projects, team, bookings and conversations belong together.</p></div>${tabs}<div class="office-toolbar"><h2>${team?'Your teams':'Your projects'}</h2><div class="row gap8">${!fan()?`<button class="btn primary" onclick="newProject(${team})">Create ${team?'team':'project'} +</button>`:''}<button class="text-btn" onclick="refreshOffice()">Refresh</button></div></div>${items.map(p=>`<article class="office-row"><div><h3>${esc(p.title)}</h3><p>${p.status==='Invitation'?'Invitation':team?p.members.filter(m=>m.status==='Accepted').length+1+' team members':esc(p.status)} / ${esc(contributionPerson(p.owner)?.name||'Owner')}</p>${!team&&p.status!=='Invitation'?`<p>${money(p.budget)} approved budget / ${p.tasks.filter(t=>t.status==='Done').length} of ${p.tasks.length} tasks complete</p>`:''}</div><button class="btn" onclick="${p.status==='Invitation'?`acceptProject('${p.id}')`:`openProject('${p.id}')`}">${p.status==='Invitation'?'Accept invitation':team?'Open team':'Open project'}</button></article>`).join('')||`<div class="empty"><h3>${team?'Build a crew you can work with again.':'Make room for the next project.'}</h3><p>${team?'Create a named team, invite people, and use its workspace for messages, documents and assets. Bring the team into your next project.':'Link the work, invite your team, and keep tasks, media, invoices and approvals together.'}</p></div>`}`}
function renderAwards(p,own){const awards=p?.awards||[];return `<section class="profile-awards"><div class="row between"><h3>Awards & recognition</h3>${own?'<button class="text-btn" onclick="editAward()">Add award +</button>':''}</div>${awards.map(a=>`<div class="office-row"><div><div class="eyebrow">${a.year} / ${esc(a.result)}</div><h3>${esc(a.title)}</h3><p>${esc(a.issuer)}${a.category?' / '+esc(a.category):''}</p>${a.url?`<a class="text-btn" href="${esc(a.url)}" target="_blank" rel="noopener noreferrer">Award / announcement</a>`:''}</div>${own?`<button class="text-btn" onclick="editAward('${a.id}')">Edit</button>`:''}</div>`).join('')||'<p style="margin-top:18px">Awards and nominations appear here when added.</p>'}</section>`}
function editAward(id=''){const a=me().awards?.find(a=>a.id===id)||{};modal(id?'Edit award':'Add an award',`<label>Award name</label><input id="award-title" maxlength="120" value="${esc(a.title||'')}"><label>Organisation / awarding body</label><input id="award-issuer" maxlength="120" value="${esc(a.issuer||'')}"><div class="grid2"><div><label>Year</label><select id="award-year">${options(Array.from({length:50},(_,i)=>String(new Date().getFullYear()-i)),String(a.year||new Date().getFullYear()))}</select></div><div><label>Recognition</label><select id="award-result">${options(['Winner','Nominee','Recognition'],a.result||'Winner')}</select></div></div><label>Category (optional)</label><input id="award-category" maxlength="120" value="${esc(a.category||'')}"><label>Announcement / media link (optional)</label><input id="award-url" type="url" value="${esc(a.url||'')}"><p>List your own awards or nominations. These are member-provided claims.</p><div id="form-error" class="error"></div>`,`<button class="btn" onclick="closeModal()">Cancel</button>${id?`<button class="text-btn" onclick="removeAward('${id}')">Remove</button>`:''}<button class="btn primary" onclick="saveAward('${id}')">Save award</button>`)}
async function saveAward(id){const a={id:id||uid(),title:document.getElementById('award-title').value.trim(),issuer:document.getElementById('award-issuer').value.trim(),year:Number(document.getElementById('award-year').value),result:document.getElementById('award-result').value,category:document.getElementById('award-category').value.trim(),url:document.getElementById('award-url').value.trim()};if(!a.title||!a.issuer||a.url&&!safeUrl(a.url))return error('Add the award, awarding body and a valid media link if available.');me().awards=(me().awards||[]).filter(x=>x.id!==id);me().awards.push(a);try{await save();closeModal();render();toast('Award saved to your profile.')}catch(e){error(e.message)}}
async function removeAward(id){me().awards=me().awards.filter(a=>a.id!==id);await save();closeModal();render();toast('Award removed.')}
async function stageProfilePhoto(input){const file=input.files[0];if(!file)return;const note=document.getElementById('photo-save-note');if(file.size>3000000||!['image/jpeg','image/png','image/webp'].includes(file.type)){note.textContent='Use JPG, PNG or WebP under 3 MB.';return}const saveButton=document.querySelector('#modal .dialog-foot .btn.primary');if(saveButton)saveButton.disabled=true;note.textContent='Uploading picture…';try{if(demoMode)profilePhotoDraft=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});else{const r=await fetch('/api/v3/photo',{method:'POST',headers:{'content-type':file.type},body:file});const data=await r.json();if(!r.ok)throw new Error(data.error);profilePhotoDraft=data.url}if(!input.isConnected)return;document.querySelector('#modal .photo-edit .avatar').innerHTML=`<img src="${esc(profilePhotoDraft)}" alt="New profile picture">`;note.textContent='Picture ready. Save profile to apply it.'}catch(e){note.textContent=e.message}finally{if(saveButton?.isConnected)saveButton.disabled=false}}
function stagePhotoRemoval(){profilePhotoDraft='';document.querySelector('#modal .photo-edit .avatar').innerHTML=initials(me().name);document.getElementById('photo-save-note').textContent='Save profile to remove the picture.'}
function gigContextChanged(){const kind=document.getElementById('gig-participation').value;document.getElementById('gig-partof').placeholder=kind==='Job'?'Client / production (optional)':kind==='Event appearance'?'Name the event':kind==='Team contribution'?'Name your team':'Name the project'}

if(['inbox','bookings'].includes(view)||location.hash.startsWith('#office'))view='office';
const emptyRateCard=()=>({title:'My rate card',intro:'',items:[],notes:'',deposit:0,style:'Minimal',business:{}});
let rateCardDraft=null,sharedRateSnapshot=null;
function messageLinks(body){return String(body).split(/(\s+)/).map(s=>messageHrefSafe(s)?`<a href="${esc(s)}" target="_blank" rel="noopener noreferrer" style="text-decoration:underline">${esc(s)}</a>`:esc(s)).join('')}
function renderRateCardSection(){const card=state.rateCard||emptyRateCard();return `<section class="profile-rate-card"><div class="row between"><h3>Your rate card</h3><button class="text-btn" onclick="designRateCard()">${card.items.length?'Edit design':'Design rate card'} +</button></div><p>Set out your services, rates and terms. Your saved card stays private until you share it.</p>${card.items.length?`<div class="row gap8 wrap"><button class="btn" onclick="previewRateCard()">Preview / save PDF</button><button class="btn primary" onclick="shareRateCard()">Share rate card</button><button class="btn" onclick="invoiceFromRateCard()">Create invoice</button></div>`:''}</section>`}
function rateRow(i){return `<div class="rate-item-editor"><label>Service</label><input class="rate-service" maxlength="100" value="${esc(i.service||'')}" placeholder="Performance / edit / photography"><div class="grid2"><div><label>Rate (ZAR)</label><input class="rate-price" type="number" min="0" value="${i.price??''}"></div><div><label>Unit</label><select class="rate-unit">${options(['Per job','Per hour','Per day','Per project','From'],i.unit||'Per job')}</select></div></div><label>What’s included (optional)</label><input class="rate-details" maxlength="200" value="${esc(i.details||'')}"><button class="text-btn" onclick="this.parentElement.remove()">Remove service</button></div>`}
function designRateCard(){rateCardDraft=structuredClone(state.rateCard||emptyRateCard());modal('Design your rate card',`<label>Card title</label><input id="rate-title" maxlength="100" value="${esc(rateCardDraft.title)}"><label>Introduction (optional)</label><textarea id="rate-intro" maxlength="300">${esc(rateCardDraft.intro)}</textarea><div class="grid2"><div><label>Layout</label><select id="rate-style">${options(['Minimal','Bold','Editorial'],rateCardDraft.style)}</select></div><div><label>Deposit (%)</label><select id="rate-deposit">${options(['0','10','20','25','30','50','75','100'],String(rateCardDraft.deposit))}</select></div></div><div id="rate-items">${(rateCardDraft.items.length?rateCardDraft.items:[{}]).map(rateRow).join('')}</div><button class="btn" onclick="addRateService()">Add service +</button>${billingFields("rate",rateCardDraft.business||{})}<p>Business and banking details appear on your card when you share it. Never add a PIN, password or card security code.</p><label>Terms / booking notes (optional)</label><textarea id="rate-notes" maxlength="800">${esc(rateCardDraft.notes)}</textarea><p>Prices are in ZAR. Rates are shared as a guide; confirm the final budget and scope for each booking.</p><div id="form-error" class="error"></div>`,'<button class="btn" onclick="closeModal()">Cancel</button><button class="btn" onclick="previewRateDraft()">Preview design</button><button class="btn primary" onclick="saveRateCard()">Save rate card</button>')}
function addRateService(){if(document.querySelectorAll('.rate-item-editor').length>=12)return toast('Keep up to 12 services.');document.getElementById('rate-items').insertAdjacentHTML('beforeend',rateRow({}))}
function captureRateCard(){const items=[...document.querySelectorAll('.rate-item-editor')].map(r=>({service:r.querySelector('.rate-service').value.trim(),price:Number(r.querySelector('.rate-price').value),unit:r.querySelector('.rate-unit').value,details:r.querySelector('.rate-details').value.trim()}));if(!document.getElementById('rate-title').value.trim()||!items.length||items.some((i,n)=>!i.service||!Number.isFinite(i.price)||i.price<0||!document.querySelectorAll('.rate-price')[n].value))throw new Error('Add a title, services and valid rates.');return {title:document.getElementById('rate-title').value.trim(),intro:document.getElementById('rate-intro').value,style:document.getElementById('rate-style').value,deposit:Number(document.getElementById('rate-deposit').value),notes:document.getElementById('rate-notes').value,business:captureBilling("rate"),items}}
async function saveRateCard(){try{state.rateCard=captureRateCard();await save();closeModal();render();toast('Rate card saved. Ready to share.')}catch(e){error(e.message)}}
function rateCardMarkup(card,name,profileRoles=[],photo=''){return `<article class="designed-rate-card ${card.style.toLowerCase()}" id="invoice-print"><div class="rate-card-header"><div><div class="brand">TAPPED <span>IN</span></div><p>${esc(name)}</p><small>${profileRoles.slice(0,5).map(esc).join(' / ')}</small></div>${photo?`<img src="${esc(photo)}" alt="${esc(name)}">`:''}</div><h2>${esc(card.title)}</h2>${card.intro?`<p class="rate-intro">${esc(card.intro)}</p>`:''}${card.items.map(i=>`<div class="rate-service-line"><div><h3>${esc(i.service)}</h3>${i.details?`<p>${esc(i.details)}</p>`:''}</div><div><strong>${money(i.price)}</strong><small>${esc(i.unit)}</small></div></div>`).join('')}<div class="rate-card-terms">${card.deposit?`<p>${card.deposit}% deposit required to confirm a booking.</p>`:''}${card.notes?`<p style="white-space:pre-wrap">${esc(card.notes)}</p>`:''}${billingMarkup(card.business)}<small>Rates in ZAR. Final scope and budget agreed per booking.</small></div></article>`}
function previewRateCard(){modal('Your rate card',rateCardMarkup(state.rateCard,me().name,me().roles,me().photo),'<button class="btn" onclick="closeModal()">Done</button><button class="btn primary" onclick="window.print()">Print / save PDF</button>')}
function previewRateDraft(){try{rateCardDraft=captureRateCard();modal('Preview your design',rateCardMarkup(rateCardDraft,me().name,me().roles,me().photo),'<button class="btn" onclick="returnRateDesigner()">Back to designer</button>')}catch(e){error(e.message)}}
function returnRateDesigner(){const saved=state.rateCard;state.rateCard=rateCardDraft;designRateCard();state.rateCard=saved}
function rateCardText(s){return `${s.name} / ${s.card.title}\n${s.card.intro}\n\n${s.card.items.map(i=>`${i.service}: ${money(i.price)} (${i.unit})`).join('\n')}\n\n${s.card.deposit?s.card.deposit+'% deposit.\n':''}${s.card.notes}\nFinal scope and budget agreed per booking.`}
let rateShareSnapshot=null,rateShareLink='';
async function shareRateCard(recipient=''){if(!state.rateCard?.items.length){toast('Design and save your rate card first.');designRateCard();return}rateShareSnapshot=null;modal('Share your rate card',`<p>Create a snapshot of your current rates. Its share link can be opened by anyone you send it to for 30 days. It contains your rate card, not your private gig earnings.</p><div id="form-error" class="error"></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="createRateShare('${recipient}')">${recipient?'Create & send to booking requester':'Create share link'}</button>`)}
async function createRateShare(recipient=''){try{rateShareSnapshot=(await api('/api/v3/rate-cards','POST',{})).snapshot;rateShareLink=demoMode?location.origin+'/demo':location.origin+'/rate-card/'+rateShareSnapshot.id;if(recipient){await sendRateToMember(recipient);return}const members=state.profiles.filter(p=>p.id!=='me');modal('Your rate card is ready to send',`${shareInvitationLinks(rateShareLink,rateShareSnapshot.name+' / '+rateShareSnapshot.card.title,rateShareSnapshot.name+' / Rate card')}<label>Rate card link</label><input readonly value="${esc(rateShareLink)}" onclick="this.select()">${members.length?`<label>Send to a member</label><select id="rate-recipient">${members.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select><button class="btn primary" onclick="sendRateToMember(document.getElementById('rate-recipient').value)">Send in Inbox</button>`:''}<p>For a PDF, use Preview / save PDF on your profile.</p>`, '<button class="btn" onclick="closeModal()">Done</button>')}catch(e){error(e.message)}}
async function sendRateToMember(pid){try{const thread=await api('/api/threads','POST',{recipient:toServer({recipient:pid}).recipient});await api('/api/threads/'+thread.id+'/messages','POST',{body:rateCardText(rateShareSnapshot)+'\n\nView the designed card: '+rateShareLink});conversationId=thread.id;inboxTab='messages';await refreshThreads();await refreshConversation();closeModal();nav('inbox');toast('Rate card sent.')}catch(e){error(e.message)}}
async function loadSharedRateCard(){try{sharedRateSnapshot=(await api('/api/v3/rate-cards/'+location.pathname.split('/').at(-1))).snapshot}catch(e){sharedRateSnapshot={error:e.message}}}
function renderSharedRateCard(){return `${siteTop()}<section class="shared-rate-page">${!sharedRateSnapshot?'<p>Loading rate card…</p>':sharedRateSnapshot.error?`<p>${esc(sharedRateSnapshot.error)}</p>`:rateCardMarkup(sharedRateSnapshot.card,sharedRateSnapshot.name,sharedRateSnapshot.roles,sharedRateSnapshot.photo)+`<div class="row gap8" style="margin-top:25px"><button class="btn" onclick="window.print()">Print / save PDF</button><button class="btn primary" onclick="openProfile('${idMap({id:sharedRateSnapshot.by},account.profile?.id||'__none__','me').id}')">View profile / request booking</button></div><p>Shared ${new Date(sharedRateSnapshot.created).toLocaleDateString('en-ZA',{timeZone:'Africa/Johannesburg'})}. Share link expires ${new Date(sharedRateSnapshot.expires).toLocaleDateString('en-ZA',{timeZone:'Africa/Johannesburg'})}.</p>`}</section>`}

if(location.pathname.startsWith('/rate-card/'))route='rate-card';
if(location.pathname.startsWith('/invite/'))route='project-invite';
startApp().then(async()=>{if(route==='stakeholder'||pendingStakeholder){await loadStakeholder();render()}if(route==='rate-card'){await loadSharedRateCard();render()}if(route==='project-invite'){await loadProjectInvite();render()}const work=new URLSearchParams(location.search).get('work');if(work)openWork(work)});
const pendingOfficeInvite=new URLSearchParams(location.search).get('invite')||'',projectInviteToken=location.pathname.startsWith('/invite/')?location.pathname.split('/').at(-1):pendingOfficeInvite;
let projectInviteDetails=null;
function shareInvitationLinks(link,message='Tap in to TAPPED IN. Connect your work, credits and people.',subject='You’re invited to TAPPED IN'){const body=message+'\n'+link;return `<div class="invite-share row wrap gap8"><a class="btn primary" href="https://wa.me/?text=${encodeURIComponent(body)}" target="_blank" rel="noopener noreferrer">Invite via WhatsApp</a><a class="btn" href="mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}">Invite via email</a></div><p class="form-help">Choose who to send it to and review your message before sending.</p>`}
function inviteSomeone(){const link=location.origin+'/signup';modal('Invite someone to tap in',`<p>Bring the people you work with into the feed. They can connect their roles, credits and socials when they join.</p>${shareInvitationLinks(link)}<label>Invitation link</label><input readonly value="${esc(link)}" onclick="this.select()">`,'<button class="btn" onclick="closeModal()">Done</button>')}
async function inviteOutsideProject(){try{if(demoMode){const link=location.origin+'/demo';modal('Invite your teammate',`<p>Demo invitations open the walkthrough. In your real office, this creates a private project invitation.</p>${shareInvitationLinks(link,'Explore the TAPPED IN creator office with me.')}`,'<button class="btn" onclick="closeModal()">Done</button>');return}const r=await api('/api/v3/project-invites','POST',{project:officeProject.id});const link=location.origin+'/invite/'+r.invite.id;modal('Invite someone who isn’t here yet',`<p>This link invites them to ${esc(officeProject.title)}. After signing in, they can join your project’s documents, assets and team chat. Share it only with the teammate you intend to invite. It expires in 14 days.</p>${shareInvitationLinks(link,'Join my project “'+officeProject.title+'” on TAPPED IN.')}<label>Private invitation link</label><input readonly value="${esc(link)}" onclick="this.select()">`,'<button class="btn" onclick="closeModal()">Done</button>')}catch(e){toast(e.message)}}
async function loadProjectInvite(){try{projectInviteDetails=await api('/api/v3/project-invites/'+projectInviteToken)}catch(e){projectInviteDetails={error:e.message}}}
function renderProjectInvite(){const p=projectInviteDetails;return `${siteTop()}<section class="onboard"><div class="eyebrow">MAKE IT TOGETHER</div><h2>You’re invited.</h2>${!p?'<p>Loading the invitation…</p>':p.error?`<p>${esc(p.error)}</p><a class="btn" href="/feed">Explore the feed</a>`:`<h3 style="margin-top:25px">${esc(p.title)}</h3><p>${esc(p.inviter)} has invited you to a project workspace. Joining gives you access to project tasks, documents, assets and team messages.</p>${!account.signedIn?`<a class="btn primary" href="/signin-with-chatgpt?return_to=${encodeURIComponent('/invite/'+projectInviteToken)}" target="_top">Sign in to join</a>`:!account.profile?`<a class="btn primary" href="/join?invite=${encodeURIComponent(projectInviteToken)}">Create your profile to join</a>`:'<button class="btn primary" onclick="acceptExternalProject()">Accept & open project</button>'}`}</section>`}
async function acceptExternalProject(){try{const r=await api('/api/v3/project-invites/'+projectInviteToken,'POST',{});officeProject=r.project;officeProjects=(await api('/api/v3/office')).projects;route='app';nav('office')}catch(e){toast(e.message)}}
function officeUploadForm(){modal('Upload media to your office',`<p>Images, video, audio and PDFs. Up to 25 MB per file. Only your accepted project team and agents with project access can open them.</p><label>Choose media</label><input id="office-upload" type="file" accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/quicktime,video/webm,audio/mpeg,audio/wav,audio/mp4,audio/ogg,application/pdf"><p id="upload-progress" role="status"></p><div id="form-error" class="error"></div>`,'<button class="btn" onclick="closeModal()">Cancel</button><button id="office-upload-submit" class="btn primary" onclick="uploadOfficeFile()">Upload to project</button>')}
async function uploadOfficeFile(){const file=document.getElementById('office-upload').files[0];if(!file)return error('Choose a media file.');if(file.size>25000000)return error('Use a file under 25 MB.');const button=document.getElementById('office-upload-submit'),progress=document.getElementById('upload-progress');button.disabled=true;progress.textContent='Uploading…';try{if(demoMode){if(file.size>2000000)throw new Error('Demo uploads are limited to 2 MB. Real projects accept 25 MB.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});officeProject.assets.push({id:uid(),title:file.name,file:true,type:file.type,size:file.size,url:data,by:account.profile.id});officeProject.version++;const projectIndex=demoData.projects.findIndex(p=>p.id===officeProject.id);demoData.projects[projectIndex]=officeProject;persistDemo()}else{const response=await fetch('/api/v3/office/'+officeProject.id+'/upload',{method:'POST',headers:{'content-type':file.type||fileMime(file.name),'x-file-name':encodeURIComponent(file.name),'x-project-version':String(officeProject.version)},body:file});const r=await response.json();if(!response.ok)throw new Error(r.error||'Upload failed.');officeProject=r.project}const ix=officeProjects.findIndex(p=>p.id===officeProject.id);if(ix>=0)officeProjects[ix]=officeProject;officeTab='assets';closeModal();render();toast('Media uploaded and saved to your project.')}catch(e){error(e.message);progress.textContent='Upload was not saved.';button.disabled=false}}
function fileMime(name){return {jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',webp:'image/webp',gif:'image/gif',mp4:'video/mp4',mov:'video/quicktime',webm:'video/webm',mp3:'audio/mpeg',wav:'audio/wav',m4a:'audio/mp4',ogg:'audio/ogg',pdf:'application/pdf'}[name.split('.').at(-1).toLowerCase()]||'application/octet-stream'}
function previewOfficeFile(id){const f=officeProject.assets.find(a=>a.id===id);if(!f)return;const media=f.type.startsWith('image/')?`<img class="office-media-preview" src="${esc(f.url)}" alt="${esc(f.title)}">`:f.type.startsWith('video/')?`<video class="office-media-preview" controls src="${esc(f.url)}"></video>`:f.type.startsWith('audio/')?`<audio controls src="${esc(f.url)}"></audio>`:'<p>This document is available to download.</p>';modal(esc(f.title),media+`<p>${(f.size/1000000).toFixed(2)} MB / Private project media</p>`,`<a class="btn primary" href="${esc(f.url)}${f.url.startsWith('data:')?'':'?download=1'}" download="${esc(f.title)}">Download</a><button class="btn" onclick="closeModal()">Done</button>`)}

function messageHrefSafe(s){try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password}catch{return false}}

function billingFields(prefix,b={},client=false){const fields=client?[['name','Client / business name'],['email','Client email'],['phone','Client phone'],['address','Billing address'],['registration','Company registration (optional)'],['taxNumber','VAT / tax number (optional)']]:[['name','Business / trading name'],['address','Business address (optional)'],['email','Business email'],['phone','Business phone'],['registration','Company registration (optional)'],['taxNumber','VAT / tax number (optional)'],['bank','Bank name'],['accountName','Account holder'],['accountNumber','Account number'],['branch','Branch / routing code'],['accountType','Account type'],['reference','Payment reference (optional)']];return `<h3 style="margin-top:25px">${client?'Client details':'Business & payment details'}</h3><div class="grid2">${fields.map(([k,label])=>`<div><label for="${prefix}-${k}">${label}</label>${k==='address'?`<textarea id="${prefix}-${k}" maxlength="500">${esc(b[k]||'')}</textarea>`:`<input id="${prefix}-${k}" maxlength="${k==='phone'?40:k==='accountNumber'||k==='branch'?50:150}" type="${k==='email'?'email':'text'}" value="${esc(b[k]||'')}">`}</div>`).join('')}</div>`}
function captureBilling(prefix){const out={};for(const k of ['name','address','email','phone','registration','taxNumber','bank','accountName','accountNumber','branch','accountType','reference'])out[k]=document.getElementById(prefix+'-'+k)?.value.trim()||'';if(out.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(out.email))throw new Error('Enter a valid email address.');return out}
function billingMarkup(b={},client=false){if(!b||!Object.values(b).some(Boolean))return '';return `<section class="billing-details"><h3>${client?'Bill to':'Business & payment details'}</h3>${['name','address','email','phone','registration','taxNumber'].filter(k=>b[k]).map(k=>`<p style="white-space:pre-wrap">${k==='registration'?'Registration: ':k==='taxNumber'?'VAT / tax: ':''}${esc(b[k])}</p>`).join('')}${!client?['bank','accountName','accountNumber','branch','accountType','reference'].filter(k=>b[k]).map(k=>`<p>${esc({bank:'Bank',accountName:'Account holder',accountNumber:'Account number',branch:'Branch / routing code',accountType:'Account type',reference:'Payment reference'}[k])}: ${esc(b[k])}</p>`).join(''):''}</section>`}
async function invoiceFromRateCard(){try{await refreshOffice();const projects=officeProjects.filter(p=>p.owner===account.profile.id&&p.type!=='team');modal('Create invoice from your rate card',`<p>Your saved services and rates will become editable invoice lines. The invoice is stored in Office.</p><label>Project</label><select id="invoice-project"><option value="">Create a new billing project</option>${projects.map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('')}</select><label>New project name</label><input id="invoice-project-name" maxlength="120" value="${esc(me().name)} / billing"><div id="form-error" class="error"></div>`,'<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="chooseInvoiceProject()">Continue to invoice</button>')}catch(e){toast(e.message)}}
async function chooseInvoiceProject(){try{const id=document.getElementById('invoice-project').value;if(id)officeProject=(await api('/api/v3/office/'+id)).project;else{const title=document.getElementById('invoice-project-name').value.trim();if(!title)return error('Name the billing project.');officeProject=(await api('/api/v3/office','POST',{project:{title,scope:'Invoices and billing',type:'project'}})).project;await refreshOffice()}officeDesk='projects';officeTab='invoices';nav('office');fullInvoiceForm(true)}catch(e){error(e.message)}}
const simpleOfficeForm=officeForm;
officeForm=function(action,id=''){if(action==='invoice')return fullInvoiceForm(false);return simpleOfficeForm(action,id)};
function fullInvoiceForm(fromCard=false){const card=state.rateCard||emptyRateCard(),business={name:me().name,...card.business},issued=new Date().toISOString().slice(0,10),due=new Date(Date.now()+30*86400000).toISOString().slice(0,10);modal(fromCard?'Rate card → invoice':'Create invoice',`${billingFields('inv-client',{},true)}${billingFields('inv-supplier',business)}<div class="grid2"><div><label>Invoice date</label><input id="inv-issued" type="date" value="${issued}"></div><div><label>Payment due</label><input id="of-due" type="date" value="${due}"></div></div><label>Purchase order / client reference (optional)</label><input id="inv-reference" maxlength="150"><h3 style="margin-top:25px">Line items / quantity / rate (ZAR)</h3><div id="invoice-lines">${(fromCard?card.items:[{}]).map(i=>invoiceLine().replace('maxlength="200"','maxlength="200" value="'+esc(i.service||'')+'"').replace('placeholder="Rate"','placeholder="Rate" value="'+(i.price??'')+'"')).join('')}</div><button class="text-btn" onclick="document.getElementById('invoice-lines').insertAdjacentHTML('beforeend',invoiceLine());updateInvoiceTotals()">Add line item +</button><label>Tax (%)</label><select id="of-tax" onchange="updateInvoiceTotals()"><option value="0">No tax / 0%</option><option value="15">VAT / 15%</option></select><p>Apply VAT only if you are registered and add your VAT number above.</p><div id="invoice-totals" aria-live="polite"></div><label>Terms / payment notes</label><textarea id="inv-notes" maxlength="1000">${esc(card.notes||'')}</textarea><p>A unique invoice number is assigned when saved. Invoice details are saved as a snapshot.</p><div id="form-error" class="error"></div>`,'<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" id="invoice-save" onclick="saveFullInvoice()">Save invoice draft</button>');document.getElementById('invoice-lines').addEventListener('input',updateInvoiceTotals);document.getElementById('invoice-lines').addEventListener('click',()=>setTimeout(updateInvoiceTotals,0));updateInvoiceTotals()}
function updateInvoiceTotals(){const subtotal=[...document.querySelectorAll('.invoice-line')].reduce((n,r)=>n+(Number(r.querySelector('.invoice-quantity').value)||0)*(Number(r.querySelector('.invoice-rate').value)||0),0),tax=Number(document.getElementById('of-tax').value);document.getElementById('invoice-totals').innerHTML=`<p>Subtotal ${money(subtotal)}<br>Tax ${money(subtotal*tax/100)}</p><h3>Total ${money(subtotal*(1+tax/100))}</h3>`}
async function saveFullInvoice(){try{const clientDetails=captureBilling('inv-client'),supplier=captureBilling('inv-supplier'),issued=document.getElementById('inv-issued').value,due=document.getElementById('of-due').value,items=[...document.querySelectorAll('.invoice-line')].map(r=>({description:r.querySelector('.invoice-description').value.trim(),quantity:Number(r.querySelector('.invoice-quantity').value),rate:Number(r.querySelector('.invoice-rate').value)}));if(!clientDetails.name||!clientDetails.address||!clientDetails.email)throw new Error('Add the client name, billing address and email.');if(!supplier.name)throw new Error('Add your business / supplier name.');if(!issued||!due||due<issued)throw new Error('Choose invoice and due dates. Due date must follow the invoice date.');if(!items.length||items.some(x=>!x.description||!Number.isFinite(x.rate)||x.rate<0||!Number.isFinite(x.quantity)||x.quantity<=0))throw new Error('Add valid descriptions, quantities and rates.');const tax=Number(document.getElementById('of-tax').value);if(tax&&!supplier.taxNumber)throw new Error('Add your registered VAT number to apply VAT.');document.getElementById('invoice-save').disabled=true;const result=await officeAction({action:'invoice',client:clientDetails.name,clientDetails,supplier,issued,due,items,tax,reference:document.getElementById('inv-reference').value,notes:document.getElementById('inv-notes').value});if(result){officeTab='invoices';render();viewInvoice(officeProject.invoices.at(-1).id)}else document.getElementById('invoice-save').disabled=false}catch(e){error(e.message)}}
viewInvoice=function(id){const i=officeProject.invoices.find(i=>i.id===id);modal('Invoice',`<article id="invoice-print"><div class="brand">TAPPED <span>IN</span></div><h2 style="margin:25px 0">${i.tax?'TAX INVOICE':'INVOICE'} / ${esc(i.number)}</h2><p>${esc(i.status)} / ZAR<br>Invoice date: ${fmt(i.issued||i.created.slice(0,10))}<br>Payment due: ${fmt(i.due)}</p><p>Project: ${esc(officeProject.title)}${i.reference?'<br>Client reference: '+esc(i.reference):''}</p><div class="grid2">${billingMarkup(i.supplier||{name:contributionPerson(officeProject.owner)?.name})}${billingMarkup(i.clientDetails||{name:i.client},true)}</div>${i.items.map(x=>`<div class="office-row"><span>${esc(x.description)}<br>${x.quantity} × ${money(x.rate)}</span><b>${money(x.quantity*x.rate)}</b></div>`).join('')}<p>Subtotal: ${money(i.subtotal)}<br>Tax (${i.tax}%): ${money(i.total-i.subtotal)}</p><h2 style="margin:20px 0">TOTAL ${money(i.total)}</h2>${i.notes?`<h3>Payment terms</h3><p style="white-space:pre-wrap">${esc(i.notes)}</p>`:''}</article>`,'<button class="btn" onclick="closeModal()">Done</button><button class="btn primary" onclick="window.print()">Print / save PDF</button>')};

function identityCategory(p){return p.kind==='fan'?'Fan':p.category||Object.keys(roleCategories).find(c=>roleCategories[c].includes(p.primaryRole||p.roles?.[0]))||'Industry member'}
function identityMarkup(p){return `<div class="primary-identity"><div class="eyebrow">${esc(identityCategory(p))}</div>${p.kind!=='fan'?`<strong>${esc(p.primaryRole||p.roles?.[0]||'Choose your primary role')}</strong>`:'<strong>Here for the culture</strong>'}</div>`}
function identityFields(prefix,p){const category=identityCategory(p),valid=roleCategories[category]?category:Object.keys(roleCategories)[0];return `<h3 style="margin:25px 0 10px">Where you belong</h3><p>Choose one main identity. Add every other skill you bring below.</p><label>Main category</label><select id="${prefix}-category" onchange="document.getElementById('${prefix}-primary').innerHTML=categoryOptions(roleCategories[this.value])">${options(Object.keys(roleCategories),valid)}</select><label>Primary subcategory / role</label><select id="${prefix}-primary">${options(roleCategories[valid],p.primaryRole||p.roles?.[0])}</select>`}
function contactFields(prefix,p){return `<h3 style="margin-top:25px">Profile contact details</h3><p>These are visible on your profile. Use your public business contact details.</p><label>Email</label><input id="${prefix}-email" type="email" maxlength="150" value="${esc(p.contactEmail||'')}"><label>Phone / WhatsApp number</label><p class="form-help">Use an international number starting with + and your country code to enable direct WhatsApp contact.</p><input id="${prefix}-phone" type="tel" maxlength="40" value="${esc(p.phone||'')}">`}
const earlierEditProfile=editProfile;
editProfile=function(){earlierEditProfile();const bio=document.getElementById('edit-bio');bio.insertAdjacentHTML('afterend',(fan()?'':identityFields('edit',me()))+contactFields('edit',me()));const block=document.querySelector('#modal .role-options');if(block)block.innerHTML=groupedSkills('roles',me().roles)};
function groupedSkills(name,selected=[]){return Object.entries(roleCategories).map(([c,rs])=>`<details ${rs.some(r=>selected.includes(r))?'open':''}><summary>${esc(c)}</summary><div class="role-options">${rs.map(r=>`<label class="role-option"><input type="checkbox" name="${name}" value="${esc(r)}" ${selected.includes(r)?'checked':''}>${esc(r)}</label>`).join('')}</div></details>`).join('')}
const earlierSaveProfile=saveProfile;
saveProfile=async function(){const email=document.getElementById('edit-email').value.trim();if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return error('Enter a valid contact email.');if(!fan()){const primary=document.getElementById('edit-primary').value;const cb=[...document.querySelectorAll('input[name=roles]')].find(c=>c.value===primary);cb.checked=true;Object.assign(me(),{category:document.getElementById('edit-category').value,primaryRole:primary})}Object.assign(me(),{contactEmail:email,phone:document.getElementById('edit-phone').value.trim()});return earlierSaveProfile()};
const earlierJoin=renderJoin;
renderJoin=function(){let html=earlierJoin();if(joinStep===1){html=html.replace('<label>Handle (optional)</label>',(joinDraft.kind==='industry'?identityFields('join',joinDraft):'')+contactFields('join',joinDraft)+'<label>Handle (optional)</label>');if(joinDraft.kind==='industry')html=html.replace(/<div class="role-options">[\s\S]*?<\/div>/,`<div class="role-options">${groupedSkills('join-roles',joinDraft.roles)}</div>`)}return html};
const earlierCaptureJoin=captureJoin;
captureJoin=function(){earlierCaptureJoin();if(joinStep!==1)return;if(document.getElementById('join-category')){joinDraft.category=document.getElementById('join-category').value;joinDraft.primaryRole=document.getElementById('join-primary').value;if(!joinDraft.roles.includes(joinDraft.primaryRole))joinDraft.roles.unshift(joinDraft.primaryRole)}else{joinDraft.category='Fan';joinDraft.primaryRole='Fan'}joinDraft.contactEmail=document.getElementById('join-email')?.value.trim()||'';joinDraft.phone=document.getElementById('join-phone')?.value.trim()||''};
const earlierPersonCard=personCard;
personCard=function(p){return earlierPersonCard(p).replace('<div class="meta">',identityMarkup(p)+'<div class="meta">')};
const earlierLanding=renderLanding;
renderLanding=function(){return earlierLanding().replace('<section class="site-section platform-hooks"',`<section class="site-section" id="who-for"><div class="eyebrow">WHO TAPPED IN IS FOR</div><h2>Every role in entertainment<br>belongs here.</h2><p>Whether you perform, produce, broadcast, sponsor, stream, support or supply, choose your place in the industry. Your main category says who you are. Your other skills show everything you can bring.</p><div class="audience-list">${Object.entries(roleCategories).map(([c,rs],i)=>`<article><span class="red">${String(i+1).padStart(2,'0')}</span><h3>${esc(c)}</h3><p>${rs.map(esc).join(' · ')}</p><a class="text-btn" href="/signup">Join as ${esc(c)}</a></article>`).join('')}<article><span class="red">FANS</span><h3>Here for the culture</h3><p>Browse the work, discover the people, tap in with appreciation, remakes and reactions, and check in at the moments you love. A fan profile stays a fan profile.</p><a class="text-btn" href="/signup">Join as a fan</a></article></div></section><section class="site-section platform-hooks"`)};
const earlierOptions=options;
options=function(items,selected='',placeholder){if(items.length&&items.some(r=>roles.includes(r))){return (placeholder?`<option value="">${esc(placeholder)}</option>`:'')+Object.entries(roleCategories).map(([cat,rs])=>{const list=rs.filter(r=>items.includes(r));return list.length?`<optgroup label="${esc(cat)}">${list.map(r=>`<option value="${esc(r)}" ${r===selected?'selected':''}>${esc(r)}</option>`).join('')}</optgroup>`:''}).join('')+items.filter(r=>!roles.includes(r)).map(r=>`<option value="${esc(r)}" ${r===selected?'selected':''}>${esc(r)}</option>`).join('')}return earlierOptions(items,selected,placeholder)};

function categoryOptions(items){return options(items)}

const pendingStakeholder=new URLSearchParams(location.search).get('stakeholder')||'',stakeholderToken=location.pathname.startsWith('/stakeholder/')?location.pathname.split('/').at(-1):pendingStakeholder;
let stakeholderDetails=null;
if(location.pathname.startsWith('/stakeholder/'))route='stakeholder';
const beforeStakeholderRender=render;
render=function(){if(route==='stakeholder'){document.documentElement.dataset.theme=state.theme;document.getElementById('app').innerHTML=renderStakeholder();return}beforeStakeholderRender()};
async function loadStakeholder(){try{stakeholderDetails=await api('/api/v3/contacts/claim/'+stakeholderToken)}catch(e){stakeholderDetails={error:e.message}}}
function renderStakeholder(){const c=stakeholderDetails;return `${siteTop()}<section class="onboard"><div class="eyebrow">YOUR PLACE IN THE INDUSTRY</div><h2>You’re invited to tap in.</h2>${!c?'<p>Loading invitation…</p>':c.error?`<p>${esc(c.error)}</p>`:c.claimed?'<p>This invitation has already been linked to a member.</p>':`<h3>${esc(c.name)}</h3><p>${esc(c.category)} / ${esc(c.role)}</p><p>${esc(c.inviter)} has added you to their contacts. Accepting links this named contact to your profile. Work credits are confirmed separately.</p>${!account.signedIn?`<a class="btn primary" target="_top" href="/signin-with-chatgpt?return_to=${encodeURIComponent('/stakeholder/'+stakeholderToken)}">Sign in to accept</a>`:!account.profile?`<a class="btn primary" href="/join?stakeholder=${encodeURIComponent(stakeholderToken)}">Create your profile</a>`:'<button class="btn primary" onclick="claimStakeholder()">Link my profile</button>'}`}</section>`}
async function claimStakeholder(){try{await api('/api/v3/contacts/claim/'+stakeholderToken,'POST',{});route='app';view='discover';render();toast('Your profile is linked to the invitation.')}catch(e){toast(e.message)}}
inviteSomeone=async function(){if(!requireAccount())return;try{const list=(await api('/api/v3/contacts')).contacts;modal('People, brands & stakeholders',`<p>Add their name now. Share a personal invitation; the contact links when they join and accept.</p><label>Name / business name</label><input id="contact-name" maxlength="100">${identityFields('contact',{roles:['Artist']})}<div id="form-error" class="error"></div><h3 style="margin-top:30px">Your contacts</h3>${list.map(c=>`<div class="office-row"><div><b>${esc(c.name)}</b><p>${esc(c.category)} / ${esc(c.role)} / ${c.member?'Linked member':'Awaiting signup'}</p></div>${c.member?`<button class="btn" onclick="closeModal();openProfile('${idMap({id:c.member},account.profile.id,'me').id}')">Profile</button>`:`<button class="btn" onclick="shareContact('${c.id}')">Invite</button>`}</div>`).join('')}`,'<button class="btn" onclick="closeModal()">Done</button><button class="btn primary" onclick="saveContact()">Add name & invite</button>')}catch(e){toast(e.message)}};
async function saveContact(){try{const r=await api('/api/v3/contacts','POST',{name:document.getElementById('contact-name').value,category:document.getElementById('contact-category').value,role:document.getElementById('contact-primary').value});shareContact(r.contact.id,r.contact.name);toast('Contact saved.')}catch(e){error(e.message)}}
async function shareContact(id,name){if(!name){try{name=(await api('/api/v3/contacts')).contacts.find(c=>c.id===id)?.name||'your contact'}catch(e){toast(e.message);return}}const link=location.origin+'/stakeholder/'+id;modal('Invite '+esc(name),`<p>Your named contact is saved. The invitation links to their profile only after they sign up and accept. It expires in 30 days.</p>${shareInvitationLinks(link,'Hi '+name+', tap in with me on TAPPED IN. Connect your work and profile.')}<label>Personal invitation link</label><input readonly value="${esc(link)}" onclick="this.select()">`,'<button class="btn" onclick="inviteSomeone()">Back to contacts</button><button class="btn" onclick="closeModal()">Done</button>')}
const beforeContactDemo=demoApi;
demoApi=async function(path,method,data){if(path==='/api/v3/contacts'){demoData.contacts=demoData.contacts||[];if(method==='POST'){const c={...data,id:uid(),owner:demoActor().id,member:''};if(!c.name.trim())throw new Error('Add a name.');demoData.contacts.push(c);persistDemo();return {contact:c}}return {contacts:demoData.contacts}}return beforeContactDemo(path,method,data)};
const beforeStakeholderJoin=renderJoin;
renderJoin=function(){if(joinStep===1&&pendingStakeholder&&stakeholderDetails&&!joinDraft.category){joinDraft.category=stakeholderDetails.category;joinDraft.primaryRole=stakeholderDetails.role;joinDraft.roles=[stakeholderDetails.role];joinDraft.name=stakeholderDetails.name}return beforeStakeholderJoin()};

const beforePublicBookings=renderBookings;
renderBookings=function(){return beforePublicBookings()+(account.profile&&!fan()?'<section class="settings-block"><h3>Need someone for the next gig?</h3><p>Post a public gig or brief with a total budget and individual role budgets. Review private bids in Opportunities before confirming your team.</p><button class="btn primary" onclick="startComposer(\'brief\')">Post public gig / brief</button></section>':'')};
